/** Bounded validation before any generated bytes become filesystem effects. */
import { resizeImage } from '@earendil-works/pi-coding-agent'
import { imageBytes } from './image-safety'
import { libraryImageDimensions } from '../library/image-dimensions'
import { MAX_IMAGE_BYTES } from './image-limits'

export { MAX_IMAGE_BYTES } from './image-limits'
const MAX_PIXELS = 64 * 1024 * 1024
export interface ValidatedImage {
  bytes: Buffer
  mimeType: string
  width: number
  height: number
  preview: { type: 'image'; data: string; mimeType: string }
}

export async function validateGeneratedImage(block: { data: string; mimeType: string }): Promise<ValidatedImage> {
  if (typeof block.data !== 'string' || !block.data || block.data.length > Math.ceil(MAX_IMAGE_BYTES / 3) * 4 ||
      block.data.length % 4 === 1 || (block.data.includes('=') && block.data.length % 4 !== 0) ||
      !/^[A-Za-z0-9+/]*={0,2}$/.test(block.data)) throw new Error('Invalid or oversized image data.')
  const bytes = Buffer.from(block.data, 'base64')
  // The actual encoding owns the extension even if a provider mislabels it.
  const header = bytes.subarray(0, 12)
  const mimeType = header.subarray(0, 8).equals(Buffer.from([137,80,78,71,13,10,26,10])) ? 'image/png'
    : header[0] === 255 && header[1] === 216 && header[2] === 255 ? 'image/jpeg'
    : /^GIF8[79]a/.test(header.toString('ascii')) ? 'image/gif'
    : header.subarray(0, 4).toString('ascii') === 'RIFF' && header.subarray(8, 12).toString('ascii') === 'WEBP' ? 'image/webp'
    : block.mimeType === 'image/svg+xml' ? 'image/svg+xml' : null
  if (!mimeType) throw new Error('The provider returned an unsupported image encoding.')
  if (mimeType === 'image/svg+xml') {
    // Preserve the original vector file. Pi image blocks require a raster
    // preview; render without loading system fonts or external resources.
    if (bytes.length > 1024 * 1024) throw new Error('SVG output exceeds the 1 MiB limit.')
    const svg = new TextDecoder('utf-8', { fatal: true }).decode(bytes)
    if (/<!DOCTYPE|<!ENTITY|<script\b|<foreignObject\b|\son[a-z]+\s*=/i.test(svg)) throw new Error('SVG output contains active content.')
    const { Resvg } = await import('@resvg/resvg-js')
    const options = { font: { loadSystemFonts: false } }
    const document = new Resvg(svg, options)
    const { width, height } = document
    if (!width || !height || width * height > MAX_PIXELS || width / height > 64 || height / width > 64 || document.imagesToResolve().length) {
      throw new Error('SVG output has unsupported dimensions or external images.')
    }
    const raster = new Resvg(svg, { ...options, fitTo: { mode: 'zoom', value: Math.min(1, 1536 / Math.max(width, height)) } }).render()
    return { bytes, mimeType, width: Math.round(width), height: Math.round(height),
      preview: { type: 'image', data: raster.asPng().toString('base64'), mimeType: 'image/png' } }
  }
  const dimensions = libraryImageDimensions(bytes)
  if (!dimensions || dimensions.imageWidth * dimensions.imageHeight > MAX_PIXELS ||
      !imageBytes({ type: 'image', data: block.data, mimeType })) throw new Error('Invalid or oversized image dimensions.')
  const decoded = await resizeImage(bytes, mimeType)
  if (!decoded) throw new Error('The provider image could not be decoded.')
  return { bytes, mimeType, width: decoded.originalWidth, height: decoded.originalHeight,
    preview: { type: 'image', data: block.data, mimeType } }
}
